package com.yeyamo_mobile.api.recommendation_service.infrastructure.persistence;import java.time.Instant;import jakarta.persistence.*;
@Entity@Table(name="recommendation_user_preferences")public class PreferenceEntity{@Id@Column(name="user_id",length=120)String userId;@Column(name="preferred_region",length=100)String preferredRegion;@Column(name="country_code",length=2)String countryCode;@Column(length=20)String language;@ElementCollection(fetch=FetchType.EAGER)@CollectionTable(name="recommendation_preference_countries",joinColumns=@JoinColumn(name="user_id"))@Column(name="country_code",length=2)Set<String>contentCountries=new HashSet<>();@ElementCollection(fetch=FetchType.EAGER)@CollectionTable(name="recommendation_preference_languages",joinColumns=@JoinColumn(name="user_id"))@Column(name="language_code",length=10)Set<String>contentLanguages=new HashSet<>();@Column(name="location_sharing_enabled",nullable=false)boolean locationSharingEnabled;@Column(name="updated_at",nullable=false)Instant updatedAt;@Version long version;}
